// words: exact
// input: u32
// output: u32
// block: 64 1 1
// overflow checks: on
#![cfg_attr(not(cpu_reference), no_std)]
#![allow(unused_mut, unused_variables, unused_assignments, unused_parens, unused_labels, unused_braces, unused_comparisons, unused_imports, dead_code, unreachable_code, arithmetic_overflow, unconditional_panic)]

#[derive(Clone, Copy)]
struct R0 { f0: i16 }

fn h2(p0: impl Fn() -> R0, p1: u16) -> [i16; 4] {
    [0_i16, 28563_i16.rotate_left((p1 as u32)), 0_i16, 0_i16]
}

fn run(input: u32) -> [u32; 1] {
    let mut l28: R0 = R0 { f0: 0_i16 };
    let mut l29: [i16; 4] = h2((move || -> R0 { R0 { f0: l28.f0 } }), 32959_u16);
    'o30: for x31 in l29.iter_mut() {
        l28.f0 = l28.f0.min((*x31));
    }
    l29 = h2((move || -> R0 { R0 { f0: l28.f0 } }), 0_u16);
    l29[(18037_u16 as usize) % 4] = l28.f0.wrapping_add(l29[(input as usize) % 4]);
    [(Some(l29[(1_u8 as usize) % 4]).unwrap_or(l28.f0) as u32)]
}

#[cfg(not(cpu_reference))]
use metal_oxide_device::{ReadBuffer, WriteBuffer, block_dim, block_idx, kernel, thread_idx};

#[cfg(not(cpu_reference))]
#[kernel]
pub unsafe fn generated(input: ReadBuffer<u32>, output: WriteBuffer<u32>, n: u32) {
    let i = block_idx().x * block_dim().x + thread_idx().x;
    if i < n {
        let words = run(unsafe { input.load_unchecked(i) });
        unsafe {
        output.store_unchecked(i * 1 + 0, words[0]);
        }
    }
}

